// The Lyren Plan mark: three kanban columns on an indigo tile. Same geometry as
// web/public/favicon.svg (generated by scripts/gen-icons.mjs). Brand colors are fixed.

import { clsx } from 'clsx';

export interface AppMarkProps {
  /** Pixel size (default 24). */
  size?: number;
  className?: string;
}

export function AppMark({ size = 24, className }: AppMarkProps) {
  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 32 32"
      aria-hidden
      focusable="false"
      className={clsx('shrink-0', className)}
    >
      <rect width="32" height="32" rx="8" fill="#4f46e5" />
      <rect x="6.5" y="7" width="5" height="18" rx="1.5" fill="#fff" />
      <rect x="13.5" y="7" width="5" height="11" rx="1.5" fill="#fff" fillOpacity="0.9" />
      <rect x="20.5" y="7" width="5" height="14.5" rx="1.5" fill="#fff" fillOpacity="0.8" />
    </svg>
  );
}
